#!/usr/bin/env bash
# ------------------------------------------------------------
# 为 REALITY "偷自己" 一键搭建伪装网站（Nginx + Let's Encrypt）
#
# 做的事情：
#   1. 安装 Nginx 和 Certbot
#   2. 部署轻量视频单页到 /var/www/mysite
#   3. 用 80 端口为你的域名申请免费证书（自动续期）
#   4. 让网站只在本机 127.0.0.1:8443 提供 HTTPS（TLS 1.3 + h2）
#   5. 检查结果，并告诉你 3x-ui 里该怎么填
#
# 公网 443 端口留给 Xray，脚本不会占用它。
# 支持 Debian / Ubuntu。用法：sudo bash setup-site.sh
# ------------------------------------------------------------
set -euo pipefail

red()    { echo -e "\033[31m$*\033[0m"; }
green()  { echo -e "\033[32m$*\033[0m"; }
yellow() { echo -e "\033[33m$*\033[0m"; }

INNER_PORT=8443
WEBROOT=/var/www/mysite
CONF=/etc/nginx/conf.d/mysite.conf
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

[[ $EUID -eq 0 ]] || { red "请用 root 运行：sudo bash $0"; exit 1; }
command -v apt-get >/dev/null || { red "本脚本只支持 Debian / Ubuntu。"; exit 1; }

# ---------- 输入 ----------
read -rp "请输入你的域名（例如 example.com）: " DOMAIN
DOMAIN="${DOMAIN,,}"
DOMAIN="${DOMAIN#http://}"; DOMAIN="${DOMAIN#https://}"; DOMAIN="${DOMAIN%%/*}"
[[ -n "$DOMAIN" ]] || { red "域名不能为空。"; exit 1; }
read -rp "请输入邮箱（证书到期提醒用，可直接回车跳过）: " EMAIL

# ---------- 1. 安装软件 ----------
green "[1/6] 安装 Nginx 和 Certbot ..."
apt-get update -y
apt-get install -y nginx certbot curl openssl

# ---------- 2. 检查域名解析和端口 ----------
green "[2/6] 检查域名解析和端口 ..."
SERVER_IP="$(curl -4 -s --max-time 8 https://api.ipify.org || true)"
DOMAIN_IP="$(getent ahostsv4 "$DOMAIN" | awk 'NR==1{print $1}' || true)"

if [[ -z "$DOMAIN_IP" ]]; then
  red "域名 $DOMAIN 解析不到 IP。请先在 DNS 里添加 A 记录指向本服务器，等几分钟再运行。"
  exit 1
fi
if [[ -n "$SERVER_IP" && "$SERVER_IP" != "$DOMAIN_IP" ]]; then
  yellow "注意：域名解析到 $DOMAIN_IP，但本服务器公网 IP 是 $SERVER_IP。"
  yellow "如果你用 Cloudflare，请把小云朵改成灰色（仅 DNS），否则 REALITY 连不上，证书也可能申请失败。"
  read -rp "仍然继续？[y/N]: " ans
  [[ "$ans" == [yY] ]] || exit 1
fi

if ss -ltnp 'sport = :80' | grep LISTEN | grep -vq nginx; then
  red "80 端口被其他程序占用（申请证书需要它）："
  ss -ltnp 'sport = :80'
  exit 1
fi
if ss -ltnp "sport = :$INNER_PORT" | grep LISTEN | grep -vq nginx; then
  red "$INNER_PORT 端口被其他程序占用："
  ss -ltnp "sport = :$INNER_PORT"
  exit 1
fi

if command -v ufw >/dev/null && ufw status | grep -q "Status: active"; then
  ufw allow 80/tcp >/dev/null && ufw allow 443/tcp >/dev/null && yellow "已在 ufw 防火墙放行 80 和 443 端口。"
fi

# ---------- 3. 放网站文件 ----------
green "[3/6] 准备网站页面 ..."
mkdir -p "$WEBROOT"
# 仅自动升级本脚本的默认博客/视频模板，保留未知的自定义首页。
BACKUP_FILE=""
backup_index() {
  if [[ -f "$WEBROOT/index.html" ]]; then
    BACKUP_FILE="$WEBROOT/index.html.bak.$(date +%Y%m%d-%H%M%S).$$"
    cp -p -- "$WEBROOT/index.html" "$BACKUP_FILE"
    yellow "原首页已备份到 $BACKUP_FILE"
  fi
}
if [[ -L "$WEBROOT/index.html" ]]; then
  yellow "首页为符号链接，保留不动；请手动检查后替换。"
elif [[ -f "$SCRIPT_DIR/index.html" && "$SCRIPT_DIR" != "$WEBROOT" ]]; then
  backup_index
  cp -- "$SCRIPT_DIR/index.html" "$WEBROOT/index.html"
  yellow "已使用脚本同目录下你自己的 index.html。"
elif [[ -f "$WEBROOT/index.html" ]] &&
     ! grep -Eq '<meta name="site-template" content="frame-video-v[12]">' "$WEBROOT/index.html" &&
     ! { grep -Fq '<title>Slow Notes</title>' "$WEBROOT/index.html" &&
         grep -Fq 'The bakery that opens at six' "$WEBROOT/index.html"; }; then
  yellow "$WEBROOT/index.html 为自定义首页，保留不动。"
else
  backup_index
cat > "$WEBROOT/index.html" <<'HTML'
