<script>
'use strict';
const covers = ["data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,","data:image/webp;base64,"];
const films = [
  {title:'Beyond the ridgeline',category:'Travel',author:'Open Roads',duration:'08:42',description:'A quiet journey above the clouds, where the trail narrows and the world opens up. Follow the ridgeline into the heart of the mountains.'},
  {title:'Where the forest breathes',category:'Nature',author:'Wild Hours',duration:'06:18',description:'Morning light moves through the canopy. A slow walk into the green, following the small details of a living forest.'},
  {title:'A place to be still',category:'Travel',author:'Elsewhere Studio',duration:'09:24',description:'Still water, distant peaks and the space between them. Discover a lakeside landscape that asks for nothing but your attention.'},
  {title:'When the city wakes',category:'City',author:'Street Journal',duration:'05:36',description:'Windows become constellations and familiar streets take on a different rhythm. A portrait of city life after the light changes.'},
  {title:'Where the ocean meets the shore',category:'Travel',author:'Open Roads',duration:'07:12',description:'An unhurried day on the coast. Warm sand, turquoise water and the simple pleasure of taking the longer route home.'},
  {title:'Into the green',category:'Nature',author:'Wild Hours',duration:'04:58',description:'Leave the road behind and follow a softer path. Light and shadow reveal a world of quiet movement beneath the trees.'},
  {title:'Before the world wakes',category:'Nature',author:'Field Notes',duration:'06:45',description:'Fog settles between the hills as the first light arrives. A small study of a landscape on the edge of waking.'},
  {title:'The ocean, uninterrupted',category:'Ocean',author:'Blue Distance',duration:'10:08',description:'An open horizon and an endless conversation between wind and water. Spend a little time with the sea.'}
];
const $ = id => document.getElementById(id);
let category = 'All films';
function card(film,index) {
  return `<article class="video-card" data-index="${index}"><a href="#watch/${index}"><div class="thumbnail"><img src="${covers[index]}" alt="${film.title}" width="480" height="270" loading="lazy" decoding="async"><span class="duration">${film.duration}</span><span class="hover-play" aria-hidden="true"><span class="triangle"></span></span></div><p class="card-category">${film.category}</p><h3>${film.title}</h3></a><p class="card-byline">${film.author} &nbsp;·&nbsp; Short film</p></article>`;
}
// 日期以服务端 SSI 输出为准；没有 SSI 时退回浏览器日期
const now = new Date();
const today = ($('hero').dataset.today.match(/^(\d{4})-(\d{2})-(\d{2})$/) || [null,now.getFullYear(),now.getMonth()+1,now.getDate()]).slice(1).map(Number);
const pick = Math.floor(Date.UTC(today[0],today[1]-1,today[2]) / 864e5) % films.length;
if (!$('hero-date').textContent.trim()) $('hero-date').textContent = new Date(Date.UTC(today[0],today[1]-1,today[2])).toLocaleDateString('en-GB',{day:'2-digit',month:'short',timeZone:'UTC'});
if (!$('year').textContent.trim()) $('year').textContent = today[0];
$('films').innerHTML = films.map((_,offset) => {const index = (pick+offset)%films.length; return card(films[index],index);}).join('');
$('hero-image').src = covers[pick];
$('hero-image').alt = films[pick].title;
$('hero-link').href = `#watch/${pick}`;
$('hero-meta').innerHTML = `${films[pick].duration} &nbsp;·&nbsp; ${films[pick].category.toUpperCase()}`;
function filterFilms() {
  const query = $('search').value.trim().toLowerCase();
  let count = 0;
  document.querySelectorAll('#films .video-card').forEach(element => {
    const film = films[element.dataset.index];
    element.hidden = !(category === 'All films' || film.category === category) || !`${film.title} ${film.category} ${film.author}`.toLowerCase().includes(query);
    if (!element.hidden) count++;
  });
  $('count').textContent = `${String(count).padStart(2,'0')} ${count === 1 ? 'FILM' : 'FILMS'}`;
  $('empty').hidden = count > 0;
}
$('search').addEventListener('input',filterFilms);
document.querySelectorAll('[data-category]').forEach(button => button.addEventListener('click',() => {
  category = button.dataset.category;
  document.querySelectorAll('[data-category]').forEach(item => item.setAttribute('aria-pressed',String(item === button)));
  filterFilms();
}));
function route(focus = true) {
  const match = location.hash.match(/^#(watch|register)(?:\/(\d+))?$/);
  const index = match ? Number(match[2] || 0) : 0;
  const view = match && films[index] ? match[1] : 'home';
  if (view === 'home' && location.hash !== '#home') history.replaceState(null,'','#home');
  ['home','watch','register'].forEach(id => { $(id).hidden = id !== view; });
  $('search-wrap').hidden = view !== 'home';
  $('registration-form').reset();
  $('registration-error').hidden = true;
  if (view === 'home') {
    document.title = 'FRAME — A different point of view';
    category = 'All films';
    $('search').value = '';
    document.querySelectorAll('[data-category]').forEach(button => button.setAttribute('aria-pressed',String(button.dataset.category === category)));
    filterFilms();
  } else {
    const film = films[index];
    document.title = `${view === 'register' ? 'Join FRAME' : film.title} — FRAME`;
    $('watch-image').src = covers[index];
    $('watch-image').alt = film.title;
    $('watch-title').textContent = film.title;
    $('watch-category').textContent = film.category;
    $('watch-author').textContent = `${film.author} · ${film.duration} · Short film`;
    $('watch-description').textContent = film.description;
    $('player-time').textContent = `00:00 / ${film.duration}`;
    $('play-link').href = `#register/${index}`;
    $('join-image').src = covers[index];
    $('join-film').textContent = film.title;
    $('join-back').href = `#watch/${index}`;
    $('related').innerHTML = [1,2].map(offset => {const next = (index+offset)%films.length; return card(films[next],next);}).join('');
  }
  if (focus) { $(view).querySelector('.view-title').focus({preventScroll:true}); window.scrollTo(0,0); }
}
$('registration-form').addEventListener('submit',event => {
  event.preventDefault();
  // The form is presentation only: never send, persist or log its input.
  event.currentTarget.reset();
  $('registration-error').hidden = false;
  $('registration-error').focus({preventScroll:true});
});
window.addEventListener('hashchange',() => route());
route(false);
</script>
</body>
</html>
HTML
  green "轻量视频页面已写入（不加载视频，不提交注册信息）。"
fi
chown -R www-data:www-data "$WEBROOT" 2>/dev/null || true

# ---------- 4. 先用 80 端口申请证书 ----------
green "[4/6] 配置 Nginx（80 端口）并申请证书 ..."
rm -f /etc/nginx/sites-enabled/default

LISTEN6_80=""
[[ -f /proc/net/if_inet6 ]] && LISTEN6_80="listen [::]:80;"

write_http_block() {
cat <<EOF
server {
    listen 80;
    $LISTEN6_80
    server_name $DOMAIN;
    server_tokens off;
    root $WEBROOT;

    location /.well-known/acme-challenge/ { try_files \$uri =404; }
    location / { return 301 https://\$host\$request_uri; }
}
EOF
}

write_http_block > "$CONF"
nginx -t
systemctl enable nginx >/dev/null 2>&1
systemctl restart nginx

if [[ -n "$EMAIL" ]]; then EMAIL_ARGS=(--email "$EMAIL"); else EMAIL_ARGS=(--register-unsafely-without-email); fi

if [[ -f "/etc/letsencrypt/live/$DOMAIN/fullchain.pem" ]]; then
  yellow "已存在 $DOMAIN 的证书，跳过申请。"
else
  certbot certonly --webroot -w "$WEBROOT" -d "$DOMAIN" \
    --non-interactive --agree-tos "${EMAIL_ARGS[@]}" \
    --deploy-hook "systemctl reload nginx"
fi

# ---------- 5. 本机 8443 提供 HTTPS 网站 ----------
green "[5/6] 配置本机 127.0.0.1:$INNER_PORT 的 HTTPS 网站 ..."
NGX_VER="$(nginx -v 2>&1 | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -1)"
if [[ "$(printf '%s\n' 1.25.1 "$NGX_VER" | sort -V | head -1)" == "1.25.1" ]]; then
  LISTEN_SSL="listen 127.0.0.1:$INNER_PORT ssl;"
  HTTP2_LINE="http2 on;"
else
  LISTEN_SSL="listen 127.0.0.1:$INNER_PORT ssl http2;"
  HTTP2_LINE=""
fi

{
write_http_block
cat <<EOF

server {
    $LISTEN_SSL
    $HTTP2_LINE
    server_name $DOMAIN;
    server_tokens off;

    ssl_certificate     /etc/letsencrypt/live/$DOMAIN/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/$DOMAIN/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;

    root $WEBROOT;
    index index.html;
    # SSI 用于在页面里输出当天日期；同时去掉 Last-Modified/ETag，表现得像动态站点
    location / { ssi on; try_files \$uri \$uri/ =404; }
}
EOF
} > "$CONF"

nginx -t
systemctl reload nginx

# ---------- 6. 检查 ----------
green "[6/6] 检查网站 ..."
HELLO="$(echo | openssl s_client -connect 127.0.0.1:$INNER_PORT -servername "$DOMAIN" -tls1_3 -alpn h2 2>/dev/null || true)"
BODY_FILE="$(mktemp)"
CODE="$(curl -s -o "$BODY_FILE" -w '%{http_code}' --max-time 8 --resolve "$DOMAIN:$INNER_PORT:127.0.0.1" "https://$DOMAIN:$INNER_PORT/" || true)"

OK=1
if echo "$HELLO" | grep -q "TLSv1.3"; then green "  ✔ 支持 TLS 1.3"; else red "  ✘ TLS 1.3 检查失败"; OK=0; fi
if echo "$HELLO" | grep -q "ALPN protocol: h2"; then green "  ✔ 支持 HTTP/2 (h2)"; else red "  ✘ h2 检查失败"; OK=0; fi
if [[ "$CODE" == "200" ]]; then green "  ✔ 网页可以正常访问"; else red "  ✘ 网页返回 $CODE"; OK=0; fi
if [[ "$CODE" == "200" ]]; then
  if grep -q '<!--#' "$BODY_FILE"; then red "  ✘ 每日日期未生效（SSI 没有处理）"; OK=0; else green "  ✔ 每日日期已生效（$(date +%F)）"; fi
fi
rm -f "$BODY_FILE"

echo
if [[ $OK -eq 1 ]]; then
  green "网站搭好了！接下来在 3x-ui 里编辑你的 VLESS + Reality 入站："
else
  yellow "有检查没通过，请把上面的输出发给我看看。3x-ui 的填法如下："
fi
cat <<EOF

  端口 (Port)          : 443
  Target (旧版叫 Dest) : 127.0.0.1:$INNER_PORT
  SNI (Server Names)   : $DOMAIN

  客户端：地址填 $DOMAIN（或服务器 IP），端口 443，SNI 填 $DOMAIN，指纹选 chrome。

  防火墙只需放行 80 和 443，不要对外开放 $INNER_PORT。
  改好后用浏览器打开 https://$DOMAIN ，可看到视频首页（每天轮换推荐影片）；外部访问成功仅代表页面链路正常。
EOF
